source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    markers = {v for row in grid for v in row if v != background}
    out = [row[:] for row in grid]
    # Complete the rectangular outer contour around the marker pattern.
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] in markers]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    for c in range(c0, c1 + 1):
        if grid[r0][c] == background: out[r0][c] = 2
        if grid[r1][c] == background: out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if grid[r][c0] == background: out[r][c0] = 2
        if grid[r][c1] == background: out[r][c1] = 2
    # Fill gaps within any row or column containing a line of at least three markers.
    for color in markers:
        for r in range(h):
            xs = [c for c in range(w) if grid[r][c] == color]
            if len(xs) >= 3:
                for c in range(xs[0], xs[-1] + 1):
                    if grid[r][c] == background: out[r][c] = 2
        for c in range(w):
            ys = [r for r in range(h) if grid[r][c] == color]
            if len(ys) >= 3:
                for r in range(ys[0], ys[-1] + 1):
                    if grid[r][c] == background: out[r][c] = 2
    return out
'''
